--
-- TOC entry 259 (class 1259 OID 19424)
-- Name: patient_notifications; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.patient_notifications AS
 SELECT n.notification_id,
    n.patient_id,
    n.prediction_id,
    r.rule_name,
    r.description AS rule_description,
    n.notification_type,
    n.title,
    n.message,
    n.status,
    n.created_at,
    n.sent_at,
    n.read_at
   FROM (public.notifications n
     LEFT JOIN public.clinical_rules r ON ((n.rule_id = r.rule_id)));


ALTER VIEW public.patient_notifications OWNER TO postgres;

--
-- TOC entry 260 (class 1259 OID 19429)
-- Name: patient_outcome_summary; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.patient_outcome_summary AS
 SELECT o.outcome_id,
    o.patient_id,
    m.metric_name,
    m.unit,
    o.baseline_value,
    o.measured_value,
    o.outcome_status,
    o.measurement_date,
    o.notes
   FROM (public.outcome_measurements o
     JOIN public.outcome_metrics m ON ((o.metric_id = m.metric_id)));


ALTER VIEW public.patient_outcome_summary OWNER TO postgres;

--
-- TOC entry 261 (class 1259 OID 19433)
-- Name: predictions; Type: TABLE; Schema: public; Owner: postgres
