CREATE TABLE public.predictions (
    prediction_id bigint NOT NULL,
    patient_id character varying(10) NOT NULL,
    model_version_id bigint NOT NULL,
    prediction_result integer NOT NULL,
    confidence_score numeric(6,4),
    prediction_timestamp timestamp without time zone DEFAULT CURRENT_TIMESTAMP,
    id bigint NOT NULL,
    created_at timestamp(6) without time zone,
    factors character varying(1000),
    model_version character varying(255),
    risk_level character varying(255),
    risk_percent double precision,
    risk_type character varying(255),
    CONSTRAINT predictions_confidence_score_check CHECK (((confidence_score >= (0)::numeric) AND (confidence_score <= (1)::numeric))),
    CONSTRAINT predictions_prediction_result_check CHECK ((prediction_result = ANY (ARRAY[0, 1])))
);


