--
-- TOC entry 271 (class 1259 OID 19477)
-- Name: provider_collaboration_summary; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.provider_collaboration_summary AS
 SELECT c.collaboration_id,
    c.patient_id,
    c.initiated_by,
    c.collaborating_provider,
    c.subject,
    c.priority,
    c.status,
    count(n.note_id) AS total_notes,
    c.created_at
   FROM (public.provider_collaborations c
     LEFT JOIN public.collaboration_notes n ON ((c.collaboration_id = n.collaboration_id)))
  GROUP BY c.collaboration_id, c.patient_id, c.initiated_by, c.collaborating_provider, c.subject, c.priority, c.status, c.created_at;


ALTER VIEW public.provider_collaboration_summary OWNER TO postgres;

