--
-- TOC entry 354 (class 1259 OID 19766)
-- Name: team_b_patient_reference; Type: VIEW; Schema: team_a_staging; Owner: postgres
--

CREATE VIEW team_a_staging.team_b_patient_reference AS
 SELECT patient_id,
    id AS team_b_numeric_id,
    first_name,
    last_name,
    concat_ws(' '::text, first_name, last_name) AS full_name,
    email,
    phone,
    gender,
    age,
    blood_group,
    doctor
   FROM public.patients;


ALTER VIEW team_a_staging.team_b_patient_reference OWNER TO postgres;

--
-- TOC entry 355 (class 1259 OID 19770)
-- Name: patient_best_matches; Type: VIEW; Schema: team_a_staging; Owner: postgres
--

CREATE VIEW team_a_staging.patient_best_matches AS
 WITH candidates AS (
         SELECT ta.staging_id,
            ta.source_id AS team_a_patient_id,
            (ta.document ->> 'name'::text) AS team_a_name,
            (ta.document ->> 'email'::text) AS team_a_email,
            (ta.document ->> 'phone'::text) AS team_a_phone,
            tb.patient_id AS team_b_patient_id,
            tb.team_b_numeric_id,
            tb.full_name AS team_b_name,
            tb.email AS team_b_email,
            tb.phone AS team_b_phone,
                CASE
                    WHEN (((ta.document ->> 'email'::text) IS NOT NULL) AND (tb.email IS NOT NULL) AND (lower(TRIM(BOTH FROM (ta.document ->> 'email'::text))) = lower(TRIM(BOTH FROM tb.email)))) THEN 100
                    WHEN (((ta.document ->> 'phone'::text) IS NOT NULL) AND (tb.phone IS NOT NULL) AND (regexp_replace((ta.document ->> 'phone'::text), '[^0-9]'::text, ''::text, 'g'::text) = regexp_replace((tb.phone)::text, '[^0-9]'::text, ''::text, 'g'::text))) THEN 90
                    WHEN ((lower(TRIM(BOTH FROM (ta.document ->> 'name'::text))) = lower(TRIM(BOTH FROM tb.full_name))) AND (lower(TRIM(BOTH FROM (ta.document ->> 'gender'::text))) = lower(TRIM(BOTH FROM tb.gender)))) THEN 80
                    WHEN (lower(TRIM(BOTH FROM (ta.document ->> 'name'::text))) = lower(TRIM(BOTH FROM tb.full_name))) THEN 60
                    ELSE 0
                END AS match_score
           FROM (team_a_staging.patients_raw ta
             CROSS JOIN team_a_staging.team_b_patient_reference tb)
        )
 SELECT staging_id,
    team_a_patient_id,
    team_a_name,
    team_a_email,
    team_a_phone,
    team_b_patient_id,
    team_b_numeric_id,
    team_b_name,
    team_b_email,
    team_b_phone,
    match_score
   FROM candidates
  WHERE (match_score > 0)
  ORDER BY team_a_patient_id, match_score DESC;


ALTER VIEW team_a_staging.patient_best_matches OWNER TO postgres;

