--
-- TOC entry 359 (class 1259 OID 19788)
-- Name: patient_match_candidates; Type: VIEW; Schema: team_a_staging; Owner: postgres
--

CREATE VIEW team_a_staging.patient_match_candidates AS
 SELECT ta.staging_id,
    ta.source_id AS team_a_patient_id,
    (ta.document ->> 'name'::text) AS team_a_name,
    (ta.document ->> 'email'::text) AS team_a_email,
    (ta.document ->> 'phone'::text) AS team_a_phone,
    tb.patient_id AS team_b_patient_id,
    tb.team_b_numeric_id,
    tb.full_name AS team_b_name,
    tb.email AS team_b_email,
    tb.phone AS team_b_phone,
        CASE
            WHEN (((ta.document ->> 'email'::text) IS NOT NULL) AND (tb.email IS NOT NULL) AND (lower(TRIM(BOTH FROM (ta.document ->> 'email'::text))) = lower(TRIM(BOTH FROM tb.email)))) THEN 'EMAIL_EXACT'::text
            WHEN (((ta.document ->> 'phone'::text) IS NOT NULL) AND (tb.phone IS NOT NULL) AND (regexp_replace((ta.document ->> 'phone'::text), '[^0-9]'::text, ''::text, 'g'::text) = regexp_replace((tb.phone)::text, '[^0-9]'::text, ''::text, 'g'::text))) THEN 'PHONE_EXACT'::text
            WHEN (lower(TRIM(BOTH FROM (ta.document ->> 'name'::text))) = lower(TRIM(BOTH FROM tb.full_name))) THEN 'NAME_EXACT'::text
            ELSE 'NO_EXACT_MATCH'::text
        END AS match_method
   FROM (team_a_staging.patients_raw ta
     CROSS JOIN team_a_staging.team_b_patient_reference tb);


ALTER VIEW team_a_staging.patient_match_candidates OWNER TO postgres;

